// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(newOwner != actor);
        // owner is address(0) initially; seed ownership to `actor` via the zero address (the initial owner)
        vm.prank(address(0));
        c.transferOwnership(actor);
        // now `actor` is the owner and transfers ownership to the fuzzed `newOwner`
        vm.prank(actor);
        c.transferOwnership(newOwner);
        // RULE: after transferOwnership(newOwner) by the owner, c.owner() == newOwner
        assertTrue(c.owner() == newOwner);
    }
}
